  "imm.desc": { fr: "Information générale sur les programmes d'immigration au Canada et préparation linguistique. Ces contenus sont éducatifs et ne constituent pas un avis juridique en immigration.", en: "General information on immigration programs in Canada and language preparation. This content is educational and does not constitute legal immigration advice.", es: "Información general sobre los programas de inmigración en Canadá y preparación lingüística. Estos contenidos son educativos y no constituyen asesoría jurídica en inmigración.", it: "Informazioni generali sui programmi di immigrazione in Canada e preparazione linguistica. Questi contenuti sono educativi e non costituiscono consulenza legale in materia di immigrazione.", pt: "Informação geral sobre os programas de imigração no Canadá e preparação linguística. Estes conteúdos são educativos e não constituem aconselhamento jurídico em imigração.", de: "Allgemeine Informationen zu Einwanderungsprogrammen in Kanada und Sprachvorbereitung. Diese Inhalte sind bildend und stellen keine rechtliche Einwanderungsberatung dar.", ht: "Enfòmasyon jeneral sou pwogram imigrasyon nan Kanada ak preparasyon lengwistik. Kontni sa yo edikatif epi yo pa konstitye yon konsèy jiridik nan imigrasyon." },
  "imm.cta": { fr: "Consultation gratuite →", en: "Free consultation →", es: "Consulta gratuita →", it: "Consulenza gratuita →", pt: "Consulta gratuita →", de: "Kostenlose Beratung →", ht: "Konsiltasyon gratis →" },
  "imm.panel.title": { fr: "Programmes d'immigration ciblés", en: "Targeted immigration programs", es: "Programas de inmigración específicos", it: "Programmi di immigrazione mirati", pt: "Programas de imigração direcionados", de: "Gezielte Einwanderungsprogramme", ht: "Pwogram imigrasyon sible" },
  "imm.s1.title": { fr: "Évaluation du profil d'immigration", en: "Immigration profile assessment", es: "Evaluación del perfil de inmigración", it: "Valutazione del profilo di immigrazione", pt: "Avaliação do perfil de imigração", de: "Bewertung des Einwanderungsprofils", ht: "Evalyasyon pwofil imigrasyon" },
  "imm.s1.desc": { fr: "Test de positionnement linguistique + analyse de votre dossier pour identifier le programme optimal (Express Entry, PEQ, MPNP, etc.).", en: "Language placement test + analysis of your file to identify the optimal program (Express Entry, PEQ, MPNP, etc.).", es: "Test de posicionamiento lingüístico + análisis de su expediente para identificar el programa óptimo.", it: "Test di posizionamento linguistico + analisi del vostro dossier per identificare il programma ottimale.", pt: "Teste de posicionamento linguístico + análise do seu dossiê para identificar o programa ideal.", de: "Sprachstandstest + Analyse Ihrer Akte zur Ermittlung des optimalen Programms.", ht: "Tès pozisyonman lengwistik + analiz dosye ou pou idantifye pwogram optimal la." },
  "imm.s2.title": { fr: "Préparation au TEF / TCF", en: "TEF / TCF preparation", es: "Preparación TEF / TCF", it: "Preparazione TEF / TCF", pt: "Preparação TEF / TCF", de: "TEF / TCF-Vorbereitung", ht: "Preparasyon TEF / TCF" },
  "imm.s2.desc": { fr: "Cours ciblés sur votre objectif de niveau (CLB) et simulations en conditions d'examen, pour aborder le test avec confiance.", en: "Courses targeted at your level goal (CLB) and exam-condition simulations, to approach the test with confidence.", es: "Cursos orientados a su objetivo de nivel (CLB) y simulaciones en condiciones de examen, para abordar la prueba con confianza.", it: "Corsi mirati al vostro obiettivo di livello (CLB) e simulazioni in condizioni d'esame, per affrontare il test con fiducia.", pt: "Cursos focados no seu objetivo de nível (CLB) e simulações em condições de exame, para abordar o teste com confiança.", de: "Auf Ihr Niveauziel (CLB) ausgerichtete Kurse und Simulationen unter Prüfungsbedingungen, um den Test selbstbewusst anzugehen.", ht: "Kou vize sou objektif nivo ou (CLB) ak similasyon nan kondisyon egzamen, pou abòde tès la ak konfyans." },
  "imm.s3.title": { fr: "Comprendre les démarches", en: "Understanding the process", es: "Comprender los trámites", it: "Comprendere le procedure", pt: "Compreender as etapas", de: "Die Schritte verstehen", ht: "Konprann demach yo" },
  "imm.s3.desc": { fr: "Ressources d'information générale sur les formulaires et les étapes. ARCADINS ne fournit pas de conseil juridique en immigration ; consultez un professionnel autorisé.", en: "General information resources on forms and steps. ARCADINS does not provide legal immigration advice; consult an authorized professional.", es: "Recursos de información general sobre formularios y etapas. ARCADINS no ofrece asesoría jurídica en inmigración; consulte a un profesional autorizado.", it: "Risorse di informazione generale su moduli e procedure. ARCADINS non fornisce consulenza legale in materia di immigrazione; rivolgetevi a un professionista autorizzato.", pt: "Recursos de informação geral sobre formulários e etapas. A ARCADINS não fornece aconselhamento jurídico em imigração; consulte um profissional autorizado.", de: "Allgemeine Informationsressourcen zu Formularen und Schritten. ARCADINS bietet keine rechtliche Einwanderungsberatung; wenden Sie sich an eine autorisierte Fachperson.", ht: "Resous enfòmasyon jeneral sou fòmilè ak etap yo. ARCADINS pa bay konsèy jiridik nan imigrasyon; konsilte yon pwofesyonèl otorize." },
  "imm.s4.title": { fr: "Intégration & Emploi au Québec", en: "Integration & Employment in Quebec", es: "Integración & Empleo en Quebec", it: "Integrazione & Lavoro in Quebec", pt: "Integração & Emprego em Quebec", de: "Integration & Beschäftigung in Quebec", ht: "Entegrasyon & Travay nan Quebec" },
  "imm.s4.desc": { fr: "Coaching d'insertion professionnelle : CV adapté au marché canadien et préparation aux entretiens d'embauche.", en: "Professional integration coaching: a CV adapted to the Canadian market and job interview preparation.", es: "Coaching de inserción profesional: CV adaptado al mercado canadiense y preparación para entrevistas.", it: "Coaching di inserimento professionale: CV adattato al mercato canadese e preparazione ai colloqui.", pt: "Coaching de inserção profissional: CV adaptado ao mercado canadense e preparação para entrevistas.", de: "Coaching zur beruflichen Eingliederung: an den kanadischen Markt angepasster Lebenslauf und Vorbereitung auf Vorstellungsgespräche.", ht: "Coaching ensèsyon pwofesyonèl: CV adapte pou mache kanadyen an ak preparasyon pou entèvyou travay." },

